/* ---------- Browser session ---------- */
/* the agent browsing for you: a small browser frame with the page it is on drawn as a wireframe, the steps under it, and
   Pause and Take over. When the page gets in its way it stops and asks, and with Take over the page is yours to use */
.bws{width:100%;max-width:440px;margin:0 auto;padding:6px}
.bws-h{display:flex;align-items:center;justify-content:space-between;gap:var(--s-3);padding:var(--s-2) 10px 10px}
.bws-ht{display:flex;flex-direction:column;min-width:0}
.bws-ht b{font-weight:500;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-st{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-ctl{display:flex;align-items:center;gap:var(--s-1);flex:none}
.bws-take[aria-pressed="true"]{background:var(--accent-bg);color:var(--accent-fg,var(--accent));box-shadow:none}
.bws-win{margin:0 var(--s-1);border-radius:var(--r-in);border:1px solid color-mix(in srgb,var(--line) 50%,transparent);overflow:hidden;transition:border-color .3s}
.bws.you .bws-win{border-color:var(--accent-mark,var(--accent))}
.bws-bar{display:flex;align-items:center;gap:var(--s-2);height:36px;padding:0 var(--s-2) 0 10px;background:var(--wash);border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent)}
.bws-dots{display:flex;gap:var(--s-1);flex:none}
.bws-dots i{width:7px;height:7px;border-radius:50%;background:var(--faint)}
.bws-url{flex:1;min-width:0;display:flex;align-items:center;gap:6px;height:24px;padding:0 10px;border-radius:var(--r-pill);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line) 50%,transparent);font-size:12px;color:var(--fg2)}
.bws-url .i{color:var(--muted)}
.bws-url span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-vp{position:relative;height:156px;overflow:hidden;background:var(--surface)}
/* the page itself, drawn small: real words where they matter, grey lines for the rest */
.bws-pg{position:absolute;left:0;right:0;top:0;padding:var(--s-3) 14px;display:flex;flex-direction:column;gap:10px;font-size:12px;color:var(--fg2);transition:transform .8s var(--ease)}
.bws-ln{display:block;height:6px;border-radius:3px;background:var(--chip)}
.bws-nav{display:flex;align-items:center;gap:var(--s-3);font-size:11.5px;color:var(--muted);white-space:nowrap}
.bws-nav b{display:flex;align-items:center;gap:6px;margin-right:auto;font-weight:500;color:var(--fg)}
.bws-nav b::before{content:"";width:12px;height:12px;border-radius:var(--r-xs);background:var(--fg)}
.bws-nav .on{color:var(--fg)}
.bws-hd{font-size:13px;font-weight:500;color:var(--fg)}
.bws-q{display:flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:var(--r-pill);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line) 50%,transparent);color:var(--fg);white-space:nowrap;overflow:hidden}
.bws-res{display:flex;flex-direction:column;gap:2px;min-width:0}
.bws-res b{font-weight:500;color:var(--pb);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;align-self:flex-start;max-width:100%}
.bws-res span{font-size:11.5px;color:var(--muted)}
.bws-cta{align-self:flex-start;height:22px;padding:0 10px;display:inline-flex;align-items:center;border-radius:var(--r-pill);background:var(--chip);font-size:11.5px;color:var(--fg2)}
.bws-tb{display:flex;flex-direction:column;border-radius:var(--r-sm);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line) 50%,transparent)}
.bws-tb div{display:flex;justify-content:space-between;gap:var(--s-3);padding:5px 10px;border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent)}
.bws-tb div:first-child{border-top:0;font-size:11.5px;color:var(--muted)}
.bws-tb .num{padding:0 var(--s-1);margin:0 -4px;border-radius:var(--r-xs);color:var(--fg);transition:background .3s,color .3s}
/* a price the agent has taken is marked like a highlighter, in the accent fill */
.bws-tb .num.hit{background:var(--accent);color:var(--on-accent)}
/* what the agent is about to press gets a ring, and its own pointer glides there */
.bws-vp .aim{outline:1.5px solid var(--accent-mark,var(--accent));outline-offset:2px;border-radius:var(--r-xs)}
.bws-cur{position:absolute;left:0;top:0;width:14px;height:14px;z-index:2;color:var(--accent-mark,var(--accent));pointer-events:none;opacity:0;transition:transform .7s var(--ease),opacity .2s}
.bws-cur.on{opacity:1}
.bws-cur svg{display:block;width:14px;height:14px;transition:transform .16s var(--ease)}
.bws-cur svg path{fill:currentColor;stroke:var(--surface);stroke-width:1.4;stroke-linejoin:round}
.bws-cur.down svg{transform:scale(.8)}
/* the page's own cookie banner, the thing in the agent's way */
.bws-ck{position:absolute;left:8px;right:8px;bottom:8px;z-index:1;display:flex;align-items:center;gap:6px;padding:6px 6px 6px 10px;border-radius:10px;background:var(--raised);box-shadow:var(--shadow-pop);font-size:12px;color:var(--fg);transform:translateY(calc(100% + 12px));transition:transform .5s var(--ease)}
.bws-ck.on{transform:none}
.bws-ck span{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-ck button{flex:none;height:24px;padding:0 9px;border-radius:var(--r-pill);font-size:11.5px;background:var(--chip);color:var(--fg)}
.bws-ck button+button{background:var(--ink);color:var(--on-ink)}
.bws:not(.you) .bws-ck button{cursor:default}
.bws-steps{list-style:none;margin:0;padding:var(--s-2) 0 0;display:flex;flex-direction:column}
.bws-s{display:flex;align-items:flex-start;gap:10px;padding:6px 10px;font-size:13px;color:var(--muted)}
.bws-s .g{width:16px;height:19.5px;display:grid;place-items:center;flex:none;color:var(--faint)}
.bws-s .g .spin{width:11px;height:11px;color:var(--accent-fg,var(--accent))}
.bws-s.done{color:var(--fg2)}.bws-s.done .g{color:var(--ok)}
.bws-s.run,.bws-s.wait{color:var(--fg)}
.bws-s.wait .g{color:var(--warn)}
.bws.paused .bws-s .g .spin{animation-play-state:paused;color:var(--muted)}
.bws-t{flex:1;min-width:0;display:flex;flex-direction:column}
.bws-t>span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-t .d{font-size:12px;color:var(--muted)}
.bws-s.wait .d{color:var(--warn)}
.bws-ask{display:flex;flex-wrap:wrap;align-items:center;gap:var(--s-2);margin-top:var(--s-2)}
.bws-sum{display:flex;align-items:center;gap:var(--s-2);margin:var(--s-2) var(--s-1) 2px;padding:10px var(--s-3);border-radius:var(--r-in);background:var(--ok-bg);font-size:13px}
.bws-sum svg{color:var(--ok);flex:none}
.bws-sum span{min-width:0}

DM.def('browser-session', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{pause}', I('pause')).replace('{search}', I('search','xs'));
  const root = $('.bws', r), stEl = $('.bws-st', r), vp = $('.bws-vp', r), url = $('.bws-url', r), list = $('.bws-steps', r);
  const pauseB = $('.bws-pause', r), takeB = $('.bws-take', r);
  // the steps the agent planned, and the pages it passes through, drawn small: a search, the site, its pricing page
  const S = [{ t:'Search "northwind pricing"' }, { t:'Open northwind.app' }, { t:'Click "Pricing"' }, { t:'Read the plans table' }, { t:'Extract prices' }];
  const NAV = on => `<div class="bws-nav"><b>Northwind</b><span>Product</span><span data-k="pricing"${on ? ' class="on"' : ''}>Pricing</span><span>Docs</span></div>`;
  const PAGES = {
    search:`<div class="bws-pg"><div class="bws-q">${I('search','xs')}<span>northwind pricing</span></div>
      <div class="bws-res"><b data-k="site">Northwind · Docs your team reads</b><span>northwind.app</span></div>
      <div class="bws-res"><b>Northwind review: is it worth it?</b><span>softwarenotes.io</span></div>
      <div class="bws-res"><b>Northwind alternatives</b><span>stackcompare.com</span></div></div>`,
    home:`<div class="bws-pg">${NAV(false)}<div class="bws-hd">Docs your team actually reads</div><span class="bws-ln" style="width:92%"></span><span class="bws-ln" style="width:68%"></span><span class="bws-cta">Start free</span></div>`,
    pricing:`<div class="bws-pg">${NAV(true)}<div class="bws-hd">Plans and pricing</div><span class="bws-ln" style="width:78%"></span>
      <div class="bws-tb"><div><span>Plan</span><span>Per seat, monthly</span></div><div><span>Starter</span><span class="num">$8</span></div><div><span>Team</span><span class="num">$16</span></div><div><span>Business</span><span class="num">$32</span></div></div><span class="bws-ln" style="width:64%"></span><span class="bws-ln" style="width:40%"></span></div>`
  };
  const G = { queued:'<span class="dot"></span>', run:'<span class="spin"></span>', wait:I('alert','xs'), done:I('ok','xs') };
  S.forEach(x => { x.el = html(`<li class="bws-s queued"><span class="g">${G.queued}</span><span class="bws-t"><span>${x.t}</span><span class="d" hidden></span></span></li>`); list.appendChild(x.el); });
  function step(i, s, d){
    const x = S[i], de = $('.d', x.el); if (x.s === s && de.textContent === (d || '')) return;
    x.s = s; x.el.className = 'bws-s ' + s; const g = $('.g', x.el); g.innerHTML = G[s]; enter(g);
    if (s === 'run' || s === 'wait') x.el.setAttribute('aria-current', 'step'); else x.el.removeAttribute('aria-current');
    if (!d){ de.hidden = true; de.textContent = ''; } else if (de.hidden){ de.textContent = d; de.hidden = false; enter(de); } else swap(de, d);
  }
  // the page's cookie banner waits below the fold of the viewport, and the agent's own pointer above it
  const ck = html('<div class="bws-ck"><span>This site uses cookies</span><button type="button">Reject all</button><button type="button">Accept all</button></div>');
  const cur = html('<span class="bws-cur" aria-hidden="true"><svg viewBox="0 0 14 14"><path d="M2 1.5l9.5 5-4.2 1.2-2 4.3z"/></svg></span>');
  vp.append(ck, cur);
  function page(k, u){
    const old = $('.bws-pg', vp), pg = html(PAGES[k]); vp.insertBefore(pg, ck); if (old) old.remove(); enter(pg);
    $('svg', url).outerHTML = I(k === 'search' ? 'search' : 'lock', 'xs'); swap($('span', url), u);
  }
  // the person can pause the agent or take the page over; either holds it wherever it is, and it waits for them when
  // the page blocks it
  let paused = false, you = false, blocked = false, finished = false, secs = 0, unblock = null;
  const held = () => paused || you;
  async function act(ms){ for (let left = ms; left > 0;){ await c.wait(100); if (!held()) left -= 100; } }
  async function aim(el){
    const v = vp.getBoundingClientRect(), b = el.getBoundingClientRect(), x = b.left - v.left + Math.min(b.width * .5, 36), y = b.top - v.top + b.height * .6;
    if (!cur.classList.contains('on')){ cur.style.transition = 'none'; cur.style.transform = `translate(${x + 30}px,${y + 40}px)`; void cur.offsetWidth; cur.style.transition = ''; cur.classList.add('on'); }
    cur.style.transform = `translate(${x}px,${y}px)`; el.classList.add('aim');
    await act(800); cur.classList.add('down'); await act(200); cur.classList.remove('down'); el.classList.remove('aim');
  }
  const clock = () => Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0');
  stEl.innerHTML = '<span class="m">Browsing</span> · <span class="num ck">0:00</span>';
  c.every(1000, () => { if (!held() && !blocked && !finished){ secs++; $('.ck', stEl).textContent = clock(); } });
  function update(){
    root.classList.toggle('you', you); root.classList.toggle('paused', paused && !you);
    swap($('.m', stEl), finished ? 'Done' : you ? 'You have control' : paused ? 'Paused' : blocked ? 'Needs you' : 'Browsing');
    const pl = paused ? 'Resume' : 'Pause'; pauseB.innerHTML = I(paused ? 'play' : 'pause'); pauseB.setAttribute('aria-label', pl); pauseB.dataset.tip = pl;
    pauseB.disabled = you || finished; takeB.disabled = finished;
    takeB.setAttribute('aria-pressed', you); takeB.textContent = you ? 'Hand back' : 'Take over';
    // while the person has the page, its buttons are theirs and the agent's pointer steps aside
    vp.inert = !you; cur.style.visibility = you ? 'hidden' : '';
    const ask = $('.bws-ask', r);
    if (blocked && !you && !ask) showAsk(); else if ((!blocked || you) && ask) ask.remove();
    if (blocked) step(3, 'wait', you ? 'Close the banner, then hand back' : 'A cookie banner covers the table');
  }
  function showAsk(){
    const ask = html('<div class="bws-ask"><button class="pill primary sm bws-allow">Allow closing it</button><button class="pill soft sm bws-you">Take over</button></div>');
    $('.bws-t', S[3].el).appendChild(ask); enter(ask);
    $('.bws-allow', ask).onclick = () => c.run(async () => {
      // the agent closes it the privacy-friendly way, with Reject all
      blocked = false; update(); step(3, 'run', 'Closing the banner');
      await aim($('button', ck)); ck.classList.remove('on'); unblock();
    });
    $('.bws-you', ask).onclick = () => takeB.click();
  }
  pauseB.onclick = () => { paused = !paused; update(); };
  takeB.onclick = () => { you = !you; if (you) paused = false; update(); };
  // with the page in hand, either banner button closes it
  $$('button', ck).forEach(b => b.onclick = () => { if (!you || !blocked) return; ck.classList.remove('on'); blocked = false; update(); unblock(); });
  // the run: search, open the site, go to pricing and scroll to the table, where a cookie banner covers it and the agent
  // asks before touching it. Once it is gone, it reads the table and takes the three prices
  c.run(async () => {
    page('search', 'northwind pricing'); step(0, 'run');
    await act(1800); step(0, 'done'); step(1, 'run');
    await aim($('[data-k="site"]', vp)); page('home', 'northwind.app');
    await act(1200); step(1, 'done'); step(2, 'run');
    await aim($('[data-k="pricing"]', vp)); page('pricing', 'northwind.app/pricing');
    await act(1000); step(2, 'done'); step(3, 'run');
    await act(600);
    const pg = $('.bws-pg', vp); pg.style.transform = `translateY(${-Math.max(0, Math.min(pg.offsetHeight - vp.clientHeight, $('.bws-tb', pg).offsetTop - 8))}px)`;
    await act(1200); ck.classList.add('on'); await act(500);
    blocked = true; update();
    await new Promise(res => { unblock = res; });
    step(3, 'run');
    await act(1400); step(3, 'done', '3 plans, priced per seat'); step(4, 'run', '0 of 3 prices');
    const cells = $$('.bws-tb .num', vp);
    for (let i = 0; i < cells.length; i++){ await aim(cells[i]); cells[i].classList.add('hit'); step(4, 'run', `${i + 1} of 3 prices`); }
    await act(500); cur.classList.remove('on');
    finished = true; step(4, 'done', '$8, $16 and $32 per seat'); update();
    const sm = html(`<div class="bws-sum">${I('ok','xs')}<span>Done · 3 prices saved to Pricing research</span></div>`); root.appendChild(sm); enter(sm);
  });
  update();
  // the preview's story: the agent stops at the cookie banner, the person allows it to close it, and it finishes
  c.story(async s => {
    await s.until(() => $('.bws-allow', r)); await s.beat(3);
    await s.tap($('.bws-allow', r)); s.away();
    await s.until(() => finished); await s.beat(3);
  });
});
